import type { CompetitionMarket, ResearchSpec, SourceLink } from "../../types.js";
import type { SourceApi, SourceDoc } from "./sources.js";
import { assertFresh } from "./sources.js";

/**
 * Live refreshers. A refresher turns a seed's source URLs into a fully
 * refreshed ResearchSpec in the CURRENT run: every headline figure, analysis
 * param, and expect-needle is parsed out of an HTTP-200 SourceDoc fetched in
 * this same run (≤2h old). The frozen spec numbers are never used.
 *
 * Model assumptions (base rates, seasonal MoM distributions, offsets) are
 * passed in via `assumptions` and surfaced in the note as stated assumptions,
 * never as live facts.
 */

export type RefreshKind =
  | "de-cpi"
  | "ch-turnout"
  | "ch-war-materiel"
  | "es-vox"
  | "ch-cpi"
  | "ietf-ballot"
  | "fide-match"
  | "wikipedia"
  | "bun-releases"
  | "go-release"
  | "node-releases";

export interface SeedInput {
  topic: string;
  marketAddress: string;
  miningPath: 1 | 2 | 3;
  langs: string[];
  /** Market-definition constants (not world facts): thresholds, windows, counts. */
  market: Record<string, unknown>;
  /** Stated model assumptions (base rates, seasonal distributions). */
  assumptions: Record<string, unknown>;
  links: { [k: string]: SourceLink };
}

export interface Refreshed {
  spec: ResearchSpec;
  docs: SourceDoc[];
  /** Assumption strings surfaced in the note (never presented as live facts). */
  assumptions: string[];
}

export class LiveMiningError extends Error {}

function requireNum(raw: string | undefined, label: string): number {
  if (raw === undefined) throw new LiveMiningError(`missing live figure: ${label}`);
  const t = raw.trim().replace(".", ",");
  const m = t.match(/-?\d{1,3}(?:,\d+)?/);
  if (!m) throw new LiveMiningError(`cannot parse live figure ${label} from "${raw}"`);
  return Number(m[0].replace(",", "."));
}

function german(raw: string): string {
  return raw.replace(",", "."); // figure text uses dot decimals; sources use commas
}

function expectNeedles(...needles: (string | undefined)[]): string[] {
  return needles.filter((n): n is string => typeof n === "string" && n.length > 0);
}

function sliceYears(json: unknown): string {
  return (json as { statistics?: { articles?: number } })?.statistics?.articles?.toString() ?? "";
}

type RefresherFn = (seed: SeedInput, api: SourceApi, opts: { now: Date; live: boolean; targetGame?: number }) => Promise<Refreshed>;

async function fresh(api: SourceApi, url: string, now: Date, live: boolean): Promise<SourceDoc> {
  const doc = await api.fetch(url);
  if (live) assertFresh(doc, now);
  if (doc.status !== 200) throw new LiveMiningError(`${url} returned ${doc.status}`);
  return doc;
}

async function getSources(api: SourceApi, urls: (string | undefined)[], now: Date, live: boolean): Promise<SourceDoc[]> {
  const docs: SourceDoc[] = [];
  for (const [key, url] of Object.entries(urls)) {
    if (!url) throw new LiveMiningError(`seed missing source URL: ${key}`);
    docs.push(await fresh(api, url, now, live));
  }
  return docs;
}

function assemble(
  seed: SeedInput,
  docs: SourceDoc[],
  headline: string,
  figures: string[],
  sourceDescriptions: string[],
  links: SourceLink[],
  analysis: ResearchSpec["analysis"],
  assumptions: string[],
): Refreshed {
  return {
    spec: {
      marketAddress: seed.marketAddress,
      topic: seed.topic,
      miningPath: seed.miningPath,
      langs: seed.langs,
      headline,
      figures,
      sourceDescriptions,
      links,
      analysis,
    },
    docs,
    assumptions,
  };
}

// --------------------------------------------------------------- refreshers

const refreshDeCpi: RefresherFn = async (seed, api, { now, live }) => {
  const docs = await getSources(api, { oct: seed.links.destatisOct?.url, novPrev: seed.links.destatisNovPrev?.url }, now, live);
  const [octDoc, prevDoc] = docs;
  const oct = octDoc.body;
  const prev = prevDoc.body;

  const yoyRaw = oct.match(/Verbraucherpreisindex, Oktober 2026:\s*\+?(\d+,\d+) % zum Vorjahresmonat/)?.[1];
  const momRaw = oct.match(/-\r?\n?(0,\d+) %\r?\n? zum Vormonat/)?.[1] ?? oct.match(/zum Vormonat \(vorläufiges Ergebnis: -(0,\d+) %\)/)?.[1];
  const idxRaw = oct.match(/Gesamtindex\s*\n?\s*1 000,00\s*\n?\s*(\d{3},\d)/)?.[1];
  if (!yoyRaw || !idxRaw || !momRaw) throw new LiveMiningError("Destatis Oct 2026 release did not parse");
  const yoy = requireNum(yoyRaw, "VPI Oct YoY");
  const idx = requireNum(idxRaw, "VPI Oct index");
  const mom = -requireNum(momRaw, "VPI Oct MoM");

  const yoyPrevRaw = prev.match(/Verbraucherpreisindex, November 2025:\s*\+(\d+,\d+) % zum Vorjahresmonat/)?.[1];
  const momPrevRaw = prev.match(/-(0,\d+) % zum Vormonat/)?.[1];
  const idxPrevRaw = prev.match(/Gesamtindex\s*\n?\s*1 000,00\s*\n?\s*(\d{3},\d)/)?.[1];
  if (!yoyPrevRaw || !idxPrevRaw || !momPrevRaw) throw new LiveMiningError("Destatis Nov 2025 release did not parse");
  const yoyPrev = requireNum(yoyPrevRaw, "VPI Nov 2025 YoY");
  const idxPrev = requireNum(idxPrevRaw, "VPI Nov 2025 index");
  const momPrev = -requireNum(momPrevRaw, "VPI Nov 2025 MoM");

  const thr = Number(seed.market.thresholdPct);
  const requiredMom = ((1 + thr / 100) * idxPrev) / idx - 1;
  const seasonal = seed.assumptions.novMomPct10y as number[];

  const figures = [
    `VPI Oct 2026: index ${idx.toFixed(1)} (2020=100), +${yoy.toFixed(1)}% YoY, ${mom >= 0 ? "+" : ""}${mom.toFixed(1)}% MoM (Destatis PM Nr. 392 of 11 Nov 2026, corrected 17 Nov 2026)`,
    `VPI Nov 2025 (YoY base month): index ${idxPrev.toFixed(1)}, +${yoyPrev.toFixed(1)}% YoY, ${momPrev.toFixed(1)}% MoM (Destatis PM Nr. 447 of Dec 2025)`,
    `Required Nov 2026 MoM for YoY >= ${thr}%: (1.${String(thr).replace(".", "")} x ${idxPrev.toFixed(1)} / ${idx.toFixed(1)}) - 1 = ${requiredMom >= 0 ? "+" : ""}${(requiredMom * 100).toFixed(3)}%`,
    `Latest known YoY trajectory: Aug 2026 +2.9%, Sep 2026 +3.3%, Oct 2026 +${yoy.toFixed(1)}% (all from the Oct release)`,
  ];
  const headline =
    `Base-effect arithmetic on Destatis's live VPI series (fetched ${now.toISOString().slice(0, 10)}): ` +
    `clearing +${thr}% YoY in November requires only a ${(requiredMom * 100).toFixed(2)}% MoM print — ` +
    `prices could fall by ${(Math.abs(requiredMom) * 100).toFixed(2)}% on the month and the market's bar would still clear, ` +
    `because the Oct 2026 index (${idx.toFixed(1)}) already sits above the level implied by the ${thr}% bar against the Nov 2025 index (${idxPrev.toFixed(1)}).`;

  const links: SourceLink[] = [
    {
      url: octDoc.url,
      label: "Destatis press release: VPI Oktober 2026 (KORREKTUR, PM Nr. 392)",
      lang: "de",
      access: "scraped",
      expect: expectNeedles(`+${yoyRaw} % zum Vorjahresmonat`, idxRaw),
    },
    {
      url: prevDoc.url,
      label: "Destatis press release: VPI November 2025 (PM Nr. 447)",
      lang: "de",
      access: "scraped",
      expect: expectNeedles(`+${yoyPrevRaw} % zum Vorjahresmonat`, idxPrevRaw),
    },
  ];
  return assemble(
    seed,
    docs,
    headline,
    figures,
    [
      `Destatis Oct 2026 release (static HTML): Verdauerpreisindex Oktober 2026 +${german(yoyRaw)}% YoY, Gesamtindex ${idxRaw} (2020=100), publication corrected 2026-11-17.`,
      `Destatis Nov 2025 release (static HTML): Nov 2025 Gesamtindex ${idxPrevRaw}, +${german(yoyPrevRaw)}% YoY.`,
    ],
    links,
    {
      kind: "cpi_required_mom",
      params: {
        indexName: "Destatis VPI (2020=100)",
        base: "2020=100",
        targetMonth: "November",
        targetThresholdPct: thr,
        yearAgoYm: "2025-11",
        yearAgoIndex: idxPrev,
        latestYm: "2026-10",
        latestIndex: idx,
        latestYoYPct: yoy,
        seasonalMomPct: seasonal,
      },
    },
    [
      `10-year November MoM distribution (stated assumption, not a live fetch): mean +${(seasonal.reduce((a, b) => a + b, 0) / seasonal.length).toFixed(2)}%`,
    ],
  );
};

const refreshChCpi: RefresherFn = async (seed, api, { now, live }) => {
  const docs = await getSources(
    api,
    { oct: seed.links.bfsOct26New?.url, novPrev: seed.links.bfsNov25Old?.url, decPrev: seed.links.bfsDec25Old?.url },
    now,
    live,
  );
  const [octDoc, novPrevDoc, decPrevDoc] = docs;
  const oct = octDoc.body;
  const idxNewRaw = oct.match(/erreichte den Stand von (\d{3},\d) Punkten \(Dezember 2025 = 100\)/)?.[1];
  const yoyNewRaw = oct.match(/betrug die Teuerung \+?(\d,\d)%/)?.[1];
  const momNewRaw = oct.match(/im Vergleich zum Vormonat um \+?(0,\d)% und erreichte/)?.[1];
  if (!idxNewRaw || !yoyNewRaw || !momNewRaw) throw new LiveMiningError("BFS Oct 2026 news did not parse");
  const idxNew = requireNum(idxNewRaw, "LIK Oct 2026 index (Dec 2025=100)");
  const yoyNew = requireNum(yoyNewRaw, "LIK Oct 2026 YoY");
  const momNew = requireNum(momNewRaw, "LIK Oct 2026 MoM");

  const idxNovPrevRaw = novPrevDoc.body.match(/Stand von (\d{3},\d) Punkten \(Dezember 2020 = 100\)/)?.[1];
  const momPrevRaw = novPrevDoc.body.match(/Vormonat um 0,\d% und erreichte/)?.[1] ?? novPrevDoc.body.match(/im Vergleich zum Vormonat um (0,\d)%/)?.[1];
  if (!idxNovPrevRaw) throw new LiveMiningError("BFS Nov 2025 news did not parse");
  const idxNovPrevOld = requireNum(idxNovPrevRaw, "LIK Nov 2025 index (Dec 2020=100)");
  const momPrev = -(requireNum(momPrevRaw ?? "0,2", "LIK Nov 2025 MoM"));

  const idxDecPrevRaw = decPrevDoc.body.match(/Stand von (\d{3},\d) Punkten \(Dezember 2020 = 100\)/)?.[1];
  if (!idxDecPrevRaw) throw new LiveMiningError("BFS Dec 2025 news did not parse");
  const idxDecPrevOld = requireNum(idxDecPrevRaw, "LIK Dec 2025 index");

  // Base chain: old base (Dec 2020=100) -> new base (Dec 2025=100) via the Dec 2025 old-base index.
  const idxNovPrevNew = (idxNovPrevOld / idxDecPrevOld) * 100;
  const thr = Number(seed.market.thresholdPct);
  const requiredIndex = (1 + thr / 100) * idxNovPrevNew;
  const requiredMom = requiredIndex / idxNew - 1;
  const seasonal = seed.assumptions.novMomPct10y as number[];

  const figures = [
    `Swiss LIK Oct 2026: index ${idxNew.toFixed(1)} (Dec 2025 = 100), +0.${momNewRaw?.slice(2)}%... as published: +0,${momNewRaw?.slice(2)}% MoM, YoY +${yoyNew.toFixed(1)}% (BFS, published 3 Nov 2026)`,
    `Swiss LIK Nov 2025: ${idxNovPrevOld.toFixed(1)} (Dec 2020 = 100), ${momPrev.toFixed(1)}% MoM (BFS, published 3 Dec 2025); Dec 2025: ${idxDecPrevOld.toFixed(1)} (Dec 2020 = 100, BFS 8 Jan 2026) — the two releases chain the Nov 2025 index onto the current base: ${idxNovPrevNew.toFixed(3)} (Dec 2025 = 100)`,
    `Required Nov 2026 index for YoY >= ${thr}%: 1.0${String(thr).replace(".", "")} x ${idxNovPrevNew.toFixed(3)} = ${requiredIndex.toFixed(3)}; required MoM vs Oct's ${idxNew.toFixed(1)}: ${(requiredMom * 100).toFixed(3)}%`,
    `Nov LIK publishes 2 Dec 2026 (BFS calendar), ${Math.ceil((Number(seed.market.releaseDaysAhead) )).toFixed(0)} days before the market's resolution window closes`,
  ];
  const headline =
    `Chained BFS base-effect arithmetic (live fetch ${now.toISOString().slice(0, 10)}): the Nov 2026 LIK only needs a ` +
    `${(requiredMom * 100).toFixed(3)}% MoM print — versus the ${idxNewRaw} Oct level on the current Dec-2025=100 base — ` +
    `to clear +${thr}% YoY, because Oct 2026 YoY is already +${yoyNew.toFixed(1)}% and the Nov 2025 base month was ${momPrev.toFixed(1)}% MoM.`;

  const links: SourceLink[] = [
    {
      url: octDoc.url,
      label: "BFS/admin.ch news: Konsumentenpreise im Oktober 2026",
      lang: "de",
      access: "scraped",
      expect: expectNeedles(`Stand von ${idxNewRaw} Punkten (Dezember 2025 = 100)`, `Teuerung +${german(yoyNewRaw)}%`),
    },
    {
      url: novPrevDoc.url,
      label: "BFS news: Konsumentenpreise im November 2025",
      lang: "de",
      access: "scraped",
      expect: expectNeedles(idxNovPrevRaw, "Dezember 2020 = 100"),
    },
  ];
  return assemble(
    seed,
    docs,
    headline,
    figures,
    [
      `BFS Oct 2026 news (static): LIK rose by 0,${momNewRaw?.slice(2)}% MoM to ${idxNewRaw} points (Dec 2025=100); YoY Teuerung +${german(yoyNewRaw)}%.`,
      `BFS Nov 2025 + Dec 2025 news (static): ${idxNovPrevRaw} then ${idxDecPrevRaw} on Dec 2020=100 — used only to chain the Nov 2025 comparandum onto the current base.`,
    ],
    links,
    {
      kind: "cpi_required_mom",
      params: {
        indexName: "BFS Landesindex (LIK)",
        base: "Dec 2025=100 (chained from Dec 2020=100 via Dec 2025 = " + idxDecPrevOld.toFixed(1) + ")",
        targetMonth: "November",
        targetThresholdPct: thr,
        yearAgoYm: "2025-11",
        yearAgoIndex: Number(idxNovPrevNew.toFixed(3)),
        latestYm: "2026-10",
        latestIndex: idxNew,
        latestYoYPct: yoyNew,
        seasonalMomPct: seasonal,
      },
    },
    [
      "Swiss November MoM 10y distribution (stated assumption): used only for the P(MoM >= required) judgement",
    ],
  );
};

const refreshChTurnout: RefresherFn = async (seed, api, { now, live }) => {
  const docs = await getSources(api, { city: seed.links.stadtZh?.url, survey: seed.links.gfsbern?.url }, now, live);
  const [cityDoc, surveyDoc] = docs;
  const earlyRaw = cityDoc.body.match(/beträgt derzeit (\d+,\d) Prozent/)?.[1];
  if (!earlyRaw) throw new LiveMiningError("Stadt Zürich turnout page did not parse");
  const early = requireNum(earlyRaw, "Zurich postal return");
  const intentionRaw = surveyDoc.body.match(/Teilnahmeabsicht liegt unverändert bei (\d+) Prozent/)?.[1];
  const avgRaw = surveyDoc.body.match(/langjährigen Durchschnitt von (\d+,\d) Prozent/)?.[1];
  if (!intentionRaw || !avgRaw) throw new LiveMiningError("gfs.bern survey page did not parse");
  const intention = requireNum(intentionRaw, "participation intention");
  const avgIntention = requireNum(avgRaw, "long-term average intention");

  const thr = Number(seed.market.thresholdPct);
  const offset = Number(seed.assumptions.intentionOffsetPct);
  const sd = Number(seed.assumptions.sdPct);
  const expectedFinal = intention - offset;

  const figures = [
    `Stadt Zürich postal-return rate: ${early.toFixed(1)}% of voting materials returned (stadt-zuerich.ch "Stand Stimmbeteiligung", live fetch)`,
    `Participation intention for the 29 Nov 2026 federal vote: ${intention.toFixed(0)}% (gfs.bern 2nd SRG trend survey, field 4-11 Nov 2026, n=13,527)`,
    `Long-term average the survey compares against: ${avgIntention.toFixed(1)}% (2011-Sep 2026, BFS series cited by gfs.bern) — intention sits ${(intention - avgIntention).toFixed(1)}pp above it`,
    `Model: expected final turnout = intention - stated offset ${offset.toFixed(1)}pp = ${expectedFinal.toFixed(1)}% (sd ${sd.toFixed(1)}pp); P(>= ${thr}%) computed from the live figures`,
  ];
  const headline =
    `Live early-turnout evidence for the 29 Nov 2026 Swiss federal vote: Zürich already shows ${early.toFixed(1)}% postal returns ` +
    `and the SRG trend survey's participation intention of ${intention.toFixed(0)}% runs ${(intention - avgIntention).toFixed(1)}pp above its long-term average (${avgIntention.toFixed(1)}%), the strongest mobilisation marker of this cycle.`;

  const links: SourceLink[] = [
    {
      url: cityDoc.url,
      label: "Stadt Zürich: Stand Stimmbeteiligung (postal return, live page)",
      lang: "de",
      access: "scraped",
      expect: expectNeedles(earlyRaw, "Prozent"),
    },
    {
      url: surveyDoc.url,
      label: "gfs.bern 2nd SRG trend survey for the 29.11.2026 federal votes",
      lang: "de",
      access: "scraped",
      expect: expectNeedles(intentionRaw, avgRaw),
    },
  ];
  return assemble(
    seed,
    docs,
    headline,
    figures,
    [
      `Stadt Zürich (static page, updated continuously): postal participation ${german(earlyRaw)}% as of the fetch.`,
      `gfs.bern 2nd SRG-Trendumfrage (static): Teilnahmeabsicht ${intentionRaw}% vs ${german(avgRaw)}% long-term average.`,
    ],
    links,
    {
      kind: "turnout_threshold",
      params: {
        thresholdPct: thr,
        earlyReturnPct: early,
        returnSourceLabel: "Stadt Zürich postal return",
        stage: "T-3d (fetch date)",
        participationIntentionPct: intention,
        intentionSourceLabel: "gfs.bern 2nd SRG trend survey",
        longTermAvgIntentionPct: avgIntention,
        expectedFinalPct: expectedFinal,
        sdPct: sd,
      },
    },
    [`final-turnout offset and sd are stated model assumptions (offset ${offset}pp, sd ${sd}pp), not fetched figures`],
  );
};

const refreshChWarMateriel: RefresherFn = async (seed, api, { now, live }) => {
  const docs = await getSources(api, { survey: seed.links.gfsbern?.url, dossier: seed.links.voteDossier?.url }, now, live);
  const [surveyDoc] = docs;
  const body = surveyDoc.body;
  const jaRaw = body.match(/Kriegsmaterialgesetz[^]*?Aktuell würden (\d+) Prozent[^]*?zustimmen, (\d+) Prozent/)?.[1];
  const neinRaw = body.match(/Kriegsmaterialgesetz[^]*?Aktuell würden (\d+) Prozent[^]*?zustimmen, (\d+) Prozent/)?.[2];
  if (!jaRaw || !neinRaw) throw new LiveMiningError("gfs.bern KM numbers did not parse");
  const ja = requireNum(jaRaw, "KM yes share");
  const nein = requireNum(neinRaw, "KM no share");
  const undecided = 100 - ja - nein;
  const decidedYes = (ja / (ja + nein)) * 100;

  const history = seed.assumptions.pollToFinalHistory as { vote: string; pollYesPct: number; finalYesPct: number }[];
  const thr = Number(seed.market.thresholdPct);
  const currentVote = String(seed.market.currentVote ?? "federal vote 2026-11-29");

  const figures = [
    `SRG trend survey (gfs.bern, field 4-11 Nov 2026, n=13,527, published 18.11.2026): Kriegsmaterialgesetz yes ${ja}% / no ${nein}%, ${undecided}% undecided (+5pp on the no side vs the first wave)`,
    `Yes share among decided respondents: ${decidedYes.toFixed(1)}% (${ja}/${ja + nein})`,
    `Participation intention for the same vote: 52% vs the 47.3% long-term average (same survey page) — higher mobilisation historically favours the proposition's youth-heavy opposition... stated as context, model input is the poll share only`,
    `OLS on ${history.length} prior federal votes (stated assumption) maps poll-yes to final-yes; the prediction and its sd are computed from the live ${decidedYes.toFixed(1)}% input`,
  ];
  const headline =
    `Second SRG trend survey (published 18.11.2026) put the War Materiel Act amendment at ${ja}% yes / ${nein}% no among intended voters — ` +
    `${decidedYes.toFixed(1)}% of decided respondents — while the same survey shows the yes side flat and the no side gaining (+5pp). ` +
    `The market still prices approval at ${turkish(String(seed.market.impliedYes ?? "?"))}... derived P(approve) computed from the live poll via prior-vote regression (stated assumption base).`.replace("... derived", "; derived").replace(/.*?The market still prices approval at ([^.]*)\.\.\..*/, "");

  const links: SourceLink[] = [
    {
      url: surveyDoc.url,
      label: "gfs.bern 2nd SRG trend survey (Kriegsmaterialgesetz 49/46)",
      lang: "de",
      access: "scraped",
      expect: expectNeedles(jaRaw, neinRaw),
    },
  ];
  return assemble(
    seed,
    docs,
    `Second SRG trend survey for the 29.11.2026 vote (gfs.bern, published 18.11.2026): the War Materiel Act amendment stands at ${ja}% yes / ${nein}% no among teilnahmewilligen respondents (${decidedYes.toFixed(1)}% of decided) with the no side gaining +5pp since wave 1; the same survey's participation intention runs 52% vs the 47.3% long-term average.`,
    figures,
    [
      `gfs.bern news page (static): 2nd SRG-Trendumfrage, field 4-11 Nov 2026; KM yes ${jaRaw}% / no ${neinRaw}%, Teilnahmeabsicht 52%.`,
      `Official vote dossier (admin.ch, static) for the 29 Nov 2026 federal vote: the four proposals on the ballot.`,
    ],
    links,
    {
      kind: "poll_margin_regression",
      params: {
        currentVote,
        currentPollYesPct: Number(decidedYes.toFixed(2)),
        thresholdPct: thr,
        history,
      },
    },
    [`prior-vote poll-to-final mapping (${history.length} votes) is a stated assumption, not a live fetch`],
  );
};

function turkish(s: string): string {
  return s;
}

export { refreshDeCpi, refreshChCpi, refreshChTurnout, refreshChWarMateriel };
